/**
 * @param {string} s
 * @return {number}
 */
var longestBalanced = function(s) {
    const n = s.length;
    const aChar = "a".charCodeAt(0);
    let res = 0;

    for (let i = 0; i < n; i++) {
        const freq = new Array(26).fill(0);

        for (let j = i; j < n; j++) {
            const code = s.charCodeAt(j) - aChar;

            freq[code]++;

            if (freq.every(val => val === 0 || val === freq[code])) {
                res = Math.max(res, j - i + 1);
            }
        }
    }

    return res;
};
